export function getHreflangAlternatives(locale: string, slug: string): Array<{locale: string; slug: string; url: string}> {
  const key = `${locale}/${slug}`;
  const entry = hreflangMap[key];
  if (!entry) return [];
  
  const domainMap: Record<string, string> = {
    "pt-BR": "https://forjadesistemas.com.br",
    "it-IT": "https://systemforge.it",
    "en": "https://systemforgesoftware.com",
    "es-ES": "https://systemforge.es"
  };
  
  return Object.entries(entry.equivalents).map(([l, s]) => ({
    locale: l,
    slug: s,
    url: `${domainMap[l]}/blog/${s}`
  }));
}
